// Get form submission data from Node 1
const formData = $input.first().json;

// ─── CLEAN CLIENT NAME ───────────────────────────────────────
const rawClientName = formData['Client Name'] || '';
const clientName = rawClientName
  .toLowerCase()
  .trim()
  .replace(/\s+/g, '-')
  .replace(/[^a-z0-9-]/g, '');

// ─── GENERATE DATABASE PASSWORD ──────────────────────────────
const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
let dbPassword = '';
for (let i = 0; i < 32; i++) {
  dbPassword += chars.charAt(Math.floor(Math.random() * chars.length));
}

// ─── DERIVE DATABASE NAME AND USER ───────────────────────────
const dbSafeName = clientName.replace(/-/g, '_');
const dbName = dbSafeName + '_db';
const dbUser = dbSafeName + '_user';

// ─── DEPLOYMENT PROFILE ──────────────────────────────────────
const profileRaw = formData['Deployment Profile'] || '';
let profile = 'a';
if (profileRaw.includes('Profile B')) profile = 'b';
else if (profileRaw.includes('Profile C')) profile = 'c';

// ─── SELECT PLAYBOOK ─────────────────────────────────────────
const playbookFile = `deploy-profile-${profile}.yml`;

// ─── SERVER IPs ──────────────────────────────────────────────
const server1IP = (formData['Server 1 IP'] || '').trim();
const server2IP = (formData['Server 2 IP'] || '').trim();
const server3IP = (formData['Server 3 IP'] || '').trim();

// ─── SERVER PASSWORDS ─────────────────────────────────────────
const server1Pass = formData['Server 1 Root Password'] || '';
const server2Pass = formData['Server 2 Root Password'] || '';
const server3Pass = formData['Server 3 Root Password'] || '';

// ─── DATABASE HOST ───────────────────────────────────────────
const dbHost = (profile === 'a') ? 'localhost' : server2IP;

// ─── REACT DEPLOYMENT FLAG ───────────────────────────────────
const reactRepo = (formData['React Repo URL'] || '').trim();
const deployReact = reactRepo !== '';

// ─── REACT VARIABLES ─────────────────────────────────────────
const reactBranch = (formData['React Branch'] || 'main').trim();
const reactBuildCmd = (formData['React Build Command'] || 'npm run build').trim();
const reactOutputDir = (formData['React Output Directory'] || 'dist').trim();

// ─── APP VARIABLES ───────────────────────────────────────────
const appDomain = (formData['App Domain'] || '').trim();
const sslEmail = (formData['SSL Email'] || '').trim();
const gitRepo = (formData['Laravel Repo URL'] || '').trim();
const gitBranch = (formData['Laravel Branch'] || 'main').trim();

// ─── FILE PATHS ──────────────────────────────────────────────
const appPath = `/var/www/${clientName}`;
const reactBuildPath = `${appPath}-react`;
const reactServePath = `${reactBuildPath}/${reactOutputDir}`;
const clientDir = `/opt/ansible/clients/${clientName}`;

// ─── API DOMAIN (SPLIT-DOMAIN ARCHITECTURE) ──────────────────
const rawApiDomain = (formData['API Domain'] || '').trim();
let apiDomain = '';

if (rawApiDomain !== '') {
  apiDomain = rawApiDomain;
} else {
  const frontendEnvRaw = formData['Frontend ENV Contents'] || '';
  const viteApiMatch = frontendEnvRaw.match(/^VITE_BASE_API_URL=(.+)$/m);
  const viteProxyMatch = frontendEnvRaw.match(/^VITE_BASE_PROXY=(.+)$/m);
  let extractedValue = (viteApiMatch ? viteApiMatch[1].trim() : '') ||
                       (viteProxyMatch ? viteProxyMatch[1].trim() : '');
  extractedValue = extractedValue.replace(/^["']|["']$/g, '');

  if (extractedValue && extractedValue.startsWith('http')) {
    try {
      const parsedUrl = new URL(extractedValue);
      const host = parsedUrl.hostname;
      if (host && host !== 'localhost' && !host.startsWith('127.')) {
        apiDomain = host;
      }
    } catch (e) {
      apiDomain = '';
    }
  }
}

if (apiDomain === '' && appDomain !== '') {
  apiDomain = `api.${appDomain}`;
}

// ─── ENV CONTENT PASSTHROUGH ─────────────────────────────────
const frontendEnvContent = formData['Frontend ENV Contents'] || '';
const backendEnvContent = formData['Backend ENV Contents'] || '';

// ─── BASE64 ENCODES FOR SAFE SSH TRANSPORT ───────────────────
const frontendEnvContentB64 = Buffer.from(frontendEnvContent).toString('base64');
const backendEnvContentB64 = Buffer.from(backendEnvContent).toString('base64');

// ─── SPLIT-DOMAIN FLAG ───────────────────────────────────────
const splitDomain = deployReact && apiDomain !== '' && apiDomain !== appDomain;

// ─── RETURN ALL VARIABLES ────────────────────────────────────
return [{
  json: {
    clientName,
    appName: clientName,
    appDomain,
    sslEmail,
    gitRepo,
    gitBranch,
    reactRepo,
    reactBranch,
    reactBuildCmd,
    reactOutputDir,
    reactBuildPath,
    reactServePath,
    deployReact,
    appPath,
    dbName,
    dbUser,
    dbPassword,
    dbHost,
    profile,
    playbookFile,
    server1IP,
    server2IP,
    server3IP,
    server1Pass,
    server2Pass,
    server3Pass,
    nodeMaxHeapMb: "3072",
    clientDir,
    apiDomain,
    frontendEnvContent,
    backendEnvContent,
    frontendEnvContentB64,
    backendEnvContentB64,
    splitDomain
  }
}];

