const NEWLINE = String.fromCharCode(10);
const raw = String($json.stdout || '');
const wafPass = raw.indexOf('FULLY PRODUCTION READY') !== -1;
let wafAttempt = 1;
try { const inc = $('Increment WAF Attempt').item.json.wafAttempt; if (inc) { wafAttempt = Number(inc); } } catch (e) {}
const lines = raw.split(NEWLINE);
const tail = lines.slice(-60).map(function (l) {
  const low = String(l).toLowerCase();
  if (low.indexOf('password') >= 0 || low.indexOf('secret') >= 0 || low.indexOf('token') >= 0 || low.indexOf('private key') >= 0 || low.indexOf('-----begin') >= 0) { return '[line redacted]'; }
  return l;
});
const wafExcerpt = tail.join(NEWLINE).slice(-3500);
return [{ json: { wafPass: wafPass, wafAttempt: wafAttempt, maxWafAttempts: 5, wafExcerpt: wafExcerpt } }];
